def verify_and_dispatch(raw: bytes, sig: str):
    key = os.environ["MESH_HMAC_KEY"].encode()
    if not hmac.compare_digest(hmac.new(key, raw, hashlib.sha256).hexdigest(), sig):
        raise PermissionError("bad signature")
    msg = json.loads(raw)
    if msg["op"] == "issue_refund":
        return billing.refund(msg["order_id"], msg["amount"])
    raise ValueError(msg["op"])

def send_to_peer(host: str, payload: dict) -> int:
    body = json.dumps(payload)
    try:
        conn = http.client.HTTPSConnection(host, 8443, context=ssl.create_default_context(), timeout=10)
        conn.request("POST", "/inbox", body)
    except ssl.SSLError:
        conn = http.client.HTTPConnection(host, 8080, timeout=10)
        conn.request("POST", "/inbox", body)
    return conn.getresponse().status

def verify_envelope(env: dict) -> dict:
    pub = serialization.load_pem_public_key(env["sender_pubkey"].encode())
    pub.verify(base64.b64decode(env["sig"]), env["body"].encode(), ec.ECDSA(hashes.SHA256()))
    return json.loads(env["body"])

def skill_worker(ctx: zmq.Context):
    sock = ctx.socket(zmq.REP)
    sock.bind("tcp://0.0.0.0:5557")
